#lbSug{position:absolute;z-index:99999;background:#fff;border:1px solid rgba(64,58,52,.14);border-radius:12px;box-shadow:0 18px 40px rgba(20,20,20,.14);overflow:hidden;display:none;text-align:left}
#lbSug a{display:flex;align-items:center;gap:12px;padding:8px 14px;color:inherit;text-decoration:none;line-height:1.25}
#lbSug a.lbA,#lbSug a:hover{background:#f6f1e9}
#lbSug img{width:52px;height:52px;object-fit:contain;flex:0 0 52px;background:#fff;border-radius:6px}
#lbSug .lbN{font-size:14px;font-weight:500;color:#141414;display:block}
#lbSug .lbR{font-size:12px;color:#8a8178;display:block;margin-top:2px}
#lbSug .lbR s{margin-right:4px}
#lbSug .lbR b{color:#141414;font-weight:600}
#lbSug .lbC{display:flex;flex-wrap:wrap;gap:6px;padding:10px 14px 4px}
#lbSug .lbC a{padding:5px 12px;border:1px solid rgba(64,58,52,.22);border-radius:999px;font-size:12.5px;gap:0}
#lbSug .lbT{border-top:1px solid rgba(64,58,52,.1);font-size:13px;justify-content:center;padding:11px 14px;color:#141414}
#lbSug .lbV{padding:14px;font-size:13px;color:#8a8178}
@media(max-width:767px){#lbSug .lbN{font-size:13.5px}
}
#lbSelo{position:fixed;left:12px;bottom:12px;z-index:99999;background:#141414;color:#fff;font:12px Jost,Arial,sans-serif;padding:7px 12px;border-radius:999px;text-decoration:none;opacity:.85}

